import { motion } from 'framer-motion';
import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function Button({
  children,
  variant = 'primary',
  size = 'md',
  className,
  ...props
}) {
  const baseStyles = "inline-flex items-center justify-center font-heading font-semibold uppercase tracking-widest transition-all duration-300";

  const variants = {
    primary: "bg-secondary text-primary hover:bg-accent hover:text-primary",
    outline: "bg-transparent border border-white/20 text-secondary hover:border-accent hover:text-accent",
    accent: "bg-accent text-primary hover:bg-secondary",
    ghost: "bg-transparent text-secondary hover:text-accent",
  };

  const sizes = {
    sm: "text-xs px-4 py-2",
    md: "text-sm px-8 py-3",
    lg: "text-base px-10 py-4",
  };

  return (
    <motion.button
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      className={cn(baseStyles, variants[variant], sizes[size], className)}
      style={{ borderRadius: 'var(--radius-button, 0px)', ...props.style }}
      {...props}
    >
      {children}
    </motion.button>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { FiX, FiMinus, FiPlus, FiTrash2, FiShoppingBag, FiCheck } from 'react-icons/fi';
import { useCartStore } from '../../store/useCartStore';
import Button from './Button';

export default function CartDrawer({ isOpen, onClose }) {
  const { items, removeFromCart, addToCart, getCartTotal, clearCart } = useCartStore();
  const navigate = useNavigate();

  const handleUpdateQuantity = (item, newQuantity) => {
    if (newQuantity <= 0) return;
    // ...
  };

  const handleCheckoutAll = () => {
    if (items.length === 0) return;
    onClose();
    navigate('/checkout');
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100]"
          />

          {/* Drawer */}
          <motion.div 
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="fixed top-0 right-0 h-full w-full max-w-md bg-neutral-900 shadow-2xl z-[101] flex flex-col border-l border-white/10"
          >
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b border-white/10 shrink-0">
              <h2 className="text-xl font-heading font-bold text-secondary uppercase tracking-wider flex items-center gap-2">
                <FiShoppingBag /> Your Cart
              </h2>
              <button 
                onClick={onClose}
                className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors"
              >
                <FiX className="w-5 h-5" />
              </button>
            </div>

            {/* Cart Items */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {items.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-gray-500 space-y-4">
                  <FiShoppingBag className="w-12 h-12 opacity-20" />
                  <p className="font-body">Your cart is empty.</p>
                  <Button variant="outline" onClick={onClose} className="mt-4">
                    Continue Shopping
                  </Button>
                </div>
              ) : (
                items.map((item) => (
                  <div key={item.cartId} className="flex gap-4 p-4 bg-neutral-950 rounded-lg border border-white/5 relative group">
                    <button 
                      onClick={() => removeFromCart(item.cartId)}
                      className="absolute top-2 right-2 p-1.5 text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity bg-neutral-900 rounded-md"
                    >
                      <FiTrash2 className="w-4 h-4" />
                    </button>

                    <div className="w-20 h-20 bg-neutral-900 rounded-md overflow-hidden shrink-0 p-2">
                      <img 
                        src={item.image || (item.uploadedImages && Object.values(item.uploadedImages)[0]) || 'https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=400'} 
                        alt={item.name} 
                        className="w-full h-full object-contain"
                      />
                    </div>

                    <div className="flex-1 min-w-0 flex flex-col justify-center">
                      <h4 className="text-sm font-heading font-semibold text-white truncate pr-6">{item.name}</h4>

                      <div className="text-xs text-gray-400 mt-1 flex flex-wrap gap-2">
                        {item.selectedSize && <span>Size: <span className="text-white">{item.selectedSize}</span></span>}
                        {item.selectedColor && <span>Color: <span className="text-white capitalize">{item.selectedColor}</span></span>}
                        {item.selectedPrints && item.selectedPrints.length > 0 && <span>Custom Prints: <span className="text-white">{item.selectedPrints.length}</span></span>}
                      </div>

                      <div className="flex items-center justify-between mt-3">
                        <span className="text-secondary font-medium">₹{item.price || item.pricePerPiece}</span>
                        <div className="text-xs text-gray-400">
                          Qty: {item.quantity}
                        </div>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>

            {/* Footer */}
            {items.length > 0 && (
              <div className="p-6 border-t border-white/10 bg-neutral-950 shrink-0">
                <div className="flex justify-between items-center mb-6">
                  <span className="text-gray-400 font-body">Subtotal</span>
                  <span className="text-2xl font-heading font-bold text-accent">₹{getCartTotal().toLocaleString()}</span>
                </div>
                <Button 
                  variant="accent" 
                  className="w-full py-4 text-lg font-semibold flex items-center justify-center gap-2"
                  onClick={handleCheckoutAll}
                >
                  <FiCheck /> Checkout All Items
                </Button>
                <button 
                  onClick={clearCart}
                  className="w-full mt-4 text-sm text-gray-500 hover:text-white transition-colors"
                >
                  Clear Cart
                </button>
              </div>
            )}
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

import { useState } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { FiHeart, FiShoppingBag } from 'react-icons/fi';
import Button from './Button';
import { useUIStore } from '../../store/useUIStore';

export default function ProductCard({ product, isWholesale = false, onQuickAdd, collectionName }) {
  const [isHovered, setIsHovered] = useState(false);
  const setQuickViewProduct = useUIStore(state => state.setQuickViewProduct);

  const handleQuickAdd = (e) => {
    e.preventDefault();
    if (onQuickAdd) {
      onQuickAdd(product);
    } else {
      setQuickViewProduct(product);
    }
  };

  return (
    <motion.div 
      className="group relative flex flex-col w-full max-w-sm"
      onHoverStart={() => setIsHovered(true)}
      onHoverEnd={() => setIsHovered(false)}
      whileHover={{ y: -5 }}
      transition={{ duration: 0.3 }}
    >
      {/* Image Container */}
      <div className="relative aspect-square overflow-hidden bg-neutral-900 mb-4 flex items-center justify-center p-2">
        <button 
          onClick={handleQuickAdd}
          className="w-full h-full flex items-center justify-center relative"
        >
          <motion.img 
            src={isHovered && product.hoverImage ? product.hoverImage : product.image}
            alt={product.name}
            className={`w-full h-full object-contain drop-shadow-2xl ${product.stockStatus === 'Out of Stock' ? 'opacity-40 grayscale' : ''}`}
            initial={{ scale: 1 }}
            animate={{ scale: isHovered ? 1.05 : 1 }}
            transition={{ duration: 0.5 }}
          />
          {product.stockStatus === 'Out of Stock' && (
            <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
              <span className="bg-primary/80 text-accent border border-accent/50 text-xs md:text-sm font-bold px-4 py-2 uppercase tracking-widest backdrop-blur-sm shadow-2xl">
                OUT OF STOCK
              </span>
            </div>
          )}
        </button>

        {/* Badges */}
        <div className="absolute top-3 left-3 flex flex-col gap-2 z-20">
          {collectionName && (
            <span className="bg-accent/20 border border-accent/50 backdrop-blur-md shadow-[0_0_10px_rgba(163,255,18,0.2)] text-accent text-[10px] font-bold px-2 py-1 uppercase tracking-wider">
              {collectionName}
            </span>
          )}
          {(!isWholesale && product.comparePrice && product.comparePrice > product.price) && (
            <span className="bg-accent text-primary text-xs font-bold px-2 py-1 uppercase tracking-wider">
              {Math.round(((product.comparePrice - product.price) / product.comparePrice) * 100)}% OFF
            </span>
          )}
          {isWholesale && (
            <span className="bg-white text-primary text-xs font-bold px-2 py-1 uppercase tracking-wider border border-white/20 shadow-sm">
              MOQ: 15 Units
            </span>
          )}
        </div>

        {/* Wishlist Button */}
        <button className="absolute top-3 right-3 p-2 bg-primary/20 backdrop-blur-sm rounded-full text-secondary hover:text-accent hover:bg-primary/50 transition-all z-10">
          <FiHeart className="w-4 h-4" />
        </button>

        {/* Quick Add (Visible on Hover) */}
        <motion.div 
          className="absolute bottom-0 left-0 w-full p-4 bg-gradient-to-t from-primary/80 to-transparent flex justify-center"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: isHovered ? 1 : 0, y: isHovered ? 0 : 20 }}
          transition={{ duration: 0.3 }}
        >
          {isWholesale ? (
            <Button variant="accent" size="sm" className="w-full flex gap-2" onClick={() => window.location.href='/wholesale'}>
              <FiShoppingBag /> Build Bulk Order
            </Button>
          ) : (
            <Button variant="secondary" size="sm" className="w-full bg-white text-primary hover:bg-accent flex gap-2" onClick={handleQuickAdd}>
              <FiShoppingBag /> {product.stockStatus === 'Out of Stock' ? 'View Details' : 'Buy Now'}
            </Button>
          )}
        </motion.div>
      </div>

      <div className="flex flex-col">
        <button 
          onClick={handleQuickAdd} 
          className="font-heading font-semibold text-lg text-secondary uppercase tracking-wider hover:text-accent transition-colors text-left"
        >
          {product.name}
        </button>
        <div className="flex justify-between items-center mt-1">
          <div className="flex items-center gap-2">
            <span className="text-secondary font-body font-medium">
              ₹{isWholesale ? product.wholesalePrice || Math.round(product.price * 0.75) : product.price}
            </span>
            {isWholesale && (
              <span className="text-accent text-xs font-body border border-accent/20 px-1.5 py-0.5 rounded-sm bg-accent/5">Wholesale</span>
            )}
            {!isWholesale && product.comparePrice && product.comparePrice > product.price && (
              <span className="text-gray-500 font-body text-sm line-through">₹{product.comparePrice}</span>
            )}
          </div>
          <div className="flex flex-col items-end gap-1">
            {product.colors && Array.isArray(product.colors) && product.colors.length > 0 ? (
              <div className="flex gap-1 items-center">
                {product.colors.map((color, index) => {
                  const isOOS = product.stockStatus === 'Out of Stock' || product.outOfStockColors?.includes(color);
                  return (
                  <div 
                    key={index} 
                    className={`w-4 h-4 border rounded-sm relative ${isOOS ? 'border-gray-600 opacity-50' : 'border-white/20'}`} 
                    style={{ backgroundColor: color }}
                    title={color + (isOOS ? ' (Out of Stock)' : '')}
                  >
                    {isOOS && (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-4 h-px bg-accent rotate-45 absolute shadow-sm"></div>
                      </div>
                    )}
                  </div>
                )})}
              </div>
            ) : (
              <span className="text-[10px] text-gray-400 font-body">1 Color</span>
            )}

            {product.sizes && Array.isArray(product.sizes) && product.sizes.length > 0 && (
              <div className="flex gap-1 items-center">
                {product.sizes.map((size, index) => {
                  const isOOS = product.stockStatus === 'Out of Stock' || product.outOfStockSizes?.includes(size);
                  return (
                  <span 
                    key={index} 
                    className={`text-[9px] font-bold border px-1 rounded-sm flex items-center justify-center min-w-[16px] h-4 relative overflow-hidden ${
                      isOOS ? 'border-white/10 text-gray-600 bg-transparent' : 'border-white/20 text-gray-400 bg-white/5'
                    }`}
                    title={size + (isOOS ? ' (Out of Stock)' : '')}
                  >
                    {size}
                    {isOOS && (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-full h-px bg-accent/70 rotate-12 absolute"></div>
                      </div>
                    )}
                  </span>
                )})}
              </div>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import { motion, AnimatePresence } from 'framer-motion';
import { FiX, FiShoppingBag, FiCheck, FiMinus, FiPlus, FiPrinter } from 'react-icons/fi';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from './Button';
import { useCartStore } from '../../store/useCartStore';
import { useUIStore } from '../../store/useUIStore';

export default function QuickViewModal({ product, isOpen, onClose, onAddToCart }) {
  const navigate = useNavigate();
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [activeImage, setActiveImage] = useState(product?.image);
  const addToCart = useCartStore(state => state.addToCart);
  const { alert } = useUIStore();

  if (!product) return null;

  const handleAddToCartOnly = () => {
    if (product.colors?.length > 0 && !selectedColor) {
      alert('Please select a color', 'error', 'Color Required');
      return;
    }
    addToCart({ ...product, selectedSize, selectedColor, quantity });
    alert('Added to cart!', 'success', 'Added');
    onClose();
  };

  const allImages = [product.image, ...(product.images || [])].filter(Boolean);

  const handleAddToCart = () => {
    if (product.sizes?.length > 0 && !selectedSize) {
      alert('Please select a size', 'error', 'Size Required');
      return;
    }
    if (product.colors?.length > 0 && !selectedColor) {
      alert('Please select a color', 'error', 'Color Required');
      return;
    }

    addToCart({ ...product, selectedSize, selectedColor, quantity, orderType: 'Retail' });
    alert('Added to cart!', 'success', 'Added');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/80 backdrop-blur-sm"
          />

          <motion.div 
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            className="relative w-full max-w-4xl bg-neutral-900 shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]"
            style={{ borderRadius: 'var(--radius-popup, 0.75rem)' }}
          >
            <button 
              onClick={onClose}
              className="absolute top-4 right-4 z-10 p-2 bg-black/50 text-white rounded-full hover:bg-black transition-colors"
            >
              <FiX className="w-5 h-5" />
            </button>

            {/* Left: Images */}
            <div className="w-full md:w-1/2 bg-neutral-950 p-6 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-white/10 shrink-0">
              <div className="aspect-square w-full max-w-md relative flex items-center justify-center mb-4">
                <img 
                  src={activeImage} 
                  alt={product.name}
                  className="w-full h-full object-contain drop-shadow-2xl"
                />
              </div>

              {allImages.length > 1 && (
                <div className="flex gap-2 overflow-x-auto pb-2 w-full max-w-md scrollbar-hide justify-center">
                  {allImages.map((img, idx) => (
                    <button 
                      key={idx}
                      onClick={() => setActiveImage(img)}
                      className={`w-16 h-16 shrink-0 rounded-lg overflow-hidden border-2 transition-colors flex items-center justify-center bg-neutral-900 ${activeImage === img ? 'border-accent' : 'border-transparent hover:border-white/30'}`}
                    >
                      <img src={img} alt="" className="w-full h-full object-contain" />
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Right: Info */}
            <div className="w-full md:w-1/2 flex flex-col flex-1 min-h-0">
              <div className="p-6 md:p-8 flex-1 overflow-y-auto min-h-0">
                <h2 className="text-3xl font-heading font-bold text-secondary uppercase tracking-wider mb-2">
                {product.name}
              </h2>

              <div className="flex items-center gap-3 mb-6">
                <span className="text-2xl text-secondary font-body font-medium">₹{product.price}</span>
                {product.comparePrice && product.comparePrice > product.price && (
                  <>
                    <span className="text-gray-500 font-body line-through">₹{product.comparePrice}</span>
                    <span className="bg-accent text-primary text-xs font-bold px-2 py-1 uppercase tracking-wider">
                      {Math.round(((product.comparePrice - product.price) / product.comparePrice) * 100)}% OFF
                    </span>
                  </>
                )}
              </div>

              {product.description && (
                <p className="text-gray-400 font-body text-sm mb-6 leading-relaxed">
                  {product.description}
                </p>
              )}

              {/* Colors */}
              {product.colors && product.colors.length > 0 && (
                <div className="mb-6">
                  <h3 className="text-sm font-heading font-semibold text-secondary uppercase tracking-wider mb-3">Color</h3>
                  <div className="flex flex-wrap gap-2">
                    {product.colors.map(color => {
                      const isOOS = product.stockStatus === 'Out of Stock' || product.outOfStockColors?.includes(color);
                      return (
                        <button
                          key={color}
                          onClick={() => !isOOS && setSelectedColor(color)}
                          disabled={isOOS}
                          className={`w-10 h-10 rounded-full border-2 transition-all flex items-center justify-center relative ${
                            selectedColor === color 
                              ? 'border-accent scale-110' 
                              : 'border-white/20 hover:border-white/50'
                          } ${isOOS ? 'opacity-50 cursor-not-allowed' : ''}`}
                          style={{ backgroundColor: color }}
                          title={color + (isOOS ? ' (Out of Stock)' : '')}
                        >
                          {selectedColor === color && !isOOS && (
                            <FiCheck className={['#ffffff', '#fff', 'white'].includes(color.toLowerCase()) ? 'text-black' : 'text-white'} />
                          )}
                          {isOOS && (
                            <div className="absolute inset-0 flex items-center justify-center">
                              <div className="w-10 h-0.5 bg-accent rotate-45 absolute shadow-sm"></div>
                            </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* Sizes */}
              {product.sizes && product.sizes.length > 0 && (
                <div className="mb-6">
                  <h3 className="text-sm font-heading font-semibold text-secondary uppercase tracking-wider mb-3">Size</h3>
                  <div className="flex flex-wrap gap-2">
                    {product.sizes.map(size => {
                      const isOOS = product.stockStatus === 'Out of Stock' || product.outOfStockSizes?.includes(size);
                      return (
                        <button
                          key={size}
                          onClick={() => !isOOS && setSelectedSize(size)}
                          disabled={isOOS}
                          className={`px-4 py-2 border transition-colors font-body text-sm relative overflow-hidden ${
                            selectedSize === size 
                              ? 'border-accent bg-accent text-primary font-medium' 
                              : isOOS 
                                ? 'border-white/10 text-gray-500 bg-white/5 cursor-not-allowed'
                                : 'border-white/20 text-gray-300 hover:border-white/50 bg-transparent'
                          }`}
                          title={isOOS ? 'Out of Stock' : ''}
                        >
                          {size}
                          {isOOS && (
                            <div className="absolute inset-0 flex items-center justify-center">
                              <div className="w-full h-px bg-accent/70 rotate-12 absolute"></div>
                            </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* Quantity */}
              <div className="mb-6">
                <h3 className="text-sm font-heading font-semibold text-secondary uppercase tracking-wider mb-3">Quantity</h3>
                <div className="flex items-center gap-4">
                  <div className="flex items-center border border-white/20 rounded-md overflow-hidden bg-neutral-900">
                    <button 
                      onClick={() => setQuantity(Math.max(1, quantity - 1))}
                      className="p-3 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                    >
                      <FiMinus />
                    </button>
                    <input 
                      type="number"
                      value={quantity}
                      readOnly
                      className="w-12 text-center bg-transparent text-white font-medium outline-none"
                    />
                    <button 
                      onClick={() => setQuantity(quantity + 1)}
                      className="p-3 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                    >
                      <FiPlus />
                    </button>
                  </div>
                </div>
              </div>

              <div className="flex gap-3 mt-8">
                <Button 
                  variant={product.stockStatus === 'Out of Stock' ? 'outline' : 'accent'}
                  className={`w-full flex justify-center items-center gap-2 ${product.stockStatus === 'Out of Stock' ? 'opacity-50 cursor-not-allowed border-accent/50 text-accent hover:bg-transparent hover:text-accent' : ''}`}
                  onClick={product.stockStatus === 'Out of Stock' ? undefined : handleAddToCart}
                  disabled={product.stockStatus === 'Out of Stock'}
                >
                  <FiShoppingBag /> {product.stockStatus === 'Out of Stock' ? 'Out of Stock' : 'Add to Cart'}
                </Button>
              </div>
            </div>

              {/* Fixed Bottom Action */}
              <div className="p-6 md:px-8 md:py-6 border-t border-white/10 bg-neutral-900 shrink-0 mt-auto">
                {product.allowCustomPrint && (
                  <button 
                    onClick={() => { onClose(); navigate('/custom-print'); }}
                    className="w-full flex justify-center items-center gap-2 py-3 text-sm text-gray-400 hover:text-accent transition-colors border border-white/10 rounded-md hover:border-accent/50"
                  >
                    <FiPrinter /> Want Custom Prints on this?
                  </button>
                )}
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FiFilter, FiX, FiSearch } from 'react-icons/fi';
import ProductCard from '../components/ui/ProductCard';
import Button from '../components/ui/Button';
import { API_URL } from '../config';

export default function Catalogue() {
  const [isMobileFiltersOpen, setIsMobileFiltersOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [priceRange, setPriceRange] = useState([0, 5000]);
  const [appliedFilters, setAppliedFilters] = useState({
    searchQuery: '',
    priceRange: [0, 5000]
  });

  const [products, setProducts] = useState([]);
  const [catalogueName, setCatalogueName] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_URL}/catalogues/live`)
      .then(res => res.json())
      .then(data => {
        if (data && data.items) {
          setCatalogueName(data.name || 'Wholesale Catalogue');
          const mapped = data.items
            .filter(item => item.productId) // skip items with missing product refs
            .map(item => ({
              _id: item.productId._id,
              name: item.productId.name,
              price: item.wholesalePrice,
              mrp: item.productId.price, // retail price shown as MRP
              image: item.productId.image,
              wholesalePrice: item.wholesalePrice,
              moq: item.moq,
              stockStatus: item.productId.stockStatus || 'In Stock',
              discountBadge: item.productId.discountBadge,
            }));
          setProducts(mapped);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Failed to fetch live catalogue:", err);
        setLoading(false);
      });
  }, []);

  // Filter Logic
  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      const matchesSearch = product.name.toLowerCase().includes(appliedFilters.searchQuery.toLowerCase());
      const matchesPrice = product.price >= appliedFilters.priceRange[0] && (appliedFilters.priceRange[1] === 5000 ? true : product.price <= appliedFilters.priceRange[1]);
      return matchesSearch && matchesPrice;
    });
  }, [products, appliedFilters]);

  const applyFilters = () => {
    setAppliedFilters({
      searchQuery,
      priceRange
    });
  };

  const clearFilters = () => {
    setSearchQuery('');
    setPriceRange([0, 5000]);
    setAppliedFilters({
      searchQuery: '',
      priceRange: [0, 5000]
    });
  };

  const FiltersContent = () => (
    <div className="space-y-8">
      {/* Search */}
      <div>
        <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider mb-4">Search</h3>
        <div className="relative">
          <input
            type="text"
            placeholder="Search products..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-neutral-900 border border-white/10 text-secondary px-4 py-3 pl-10 rounded-sm focus:outline-none focus:border-accent transition-colors"
          />
          <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
        </div>
      </div>

      {/* Price Range */}
      <div>
        <div className="flex justify-between mb-4">
          <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider">Price Range</h3>
          <span className="text-accent text-sm">₹{priceRange[0]} - {priceRange[1] === 5000 ? '₹5000+' : `₹${priceRange[1]}`}</span>
        </div>
        <input
          type="range"
          min="0"
          max="5000"
          step="50"
          value={priceRange[1]}
          onChange={(e) => setPriceRange([priceRange[0], parseInt(e.target.value)])}
          className="w-full accent-accent bg-neutral-900 h-1 rounded-full appearance-none outline-none"
        />
      </div>

      <Button variant="primary" size="sm" onClick={applyFilters} className="w-full mb-3">
        Apply Filters
      </Button>
      <Button variant="outline" size="sm" onClick={clearFilters} className="w-full">
        Clear All Filters
      </Button>
    </div>
  );

  return (
    <div className="min-h-screen pt-24 pb-20 bg-primary">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 border-b border-white/10 pb-8">
          <div>
            <h1 className="text-5xl md:text-7xl font-heading font-bold text-secondary uppercase tracking-tighter">
              Wholesale <span className="text-accent italic">Catalogue</span>
            </h1>
            <p className="text-gray-400 mt-2 font-body flex items-center gap-2">
              <span className="bg-accent/10 text-accent px-2 py-0.5 rounded-sm border border-accent/20 text-xs font-semibold uppercase tracking-wider">{catalogueName}</span>
              Showing {filteredProducts.length} results
            </p>
          </div>

          <button
            className="md:hidden mt-6 flex items-center gap-2 text-secondary hover:text-accent"
            onClick={() => setIsMobileFiltersOpen(true)}
          >
            <FiFilter /> Filters
          </button>
        </div>

        <div className="flex flex-col md:flex-row gap-12">
          {/* Desktop Sidebar */}
          <aside className="hidden md:block w-64 shrink-0">
            <FiltersContent />
          </aside>

          {/* Product Grid */}
          <div className="flex-1">
            {loading ? (
              <div className="flex flex-col items-center justify-center py-20 text-center text-gray-400">
                Loading catalogue...
              </div>
            ) : filteredProducts.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
                {filteredProducts.map(product => (
                  <ProductCard key={product._id} product={product} isWholesale={true} />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center border border-white/10 rounded-sm bg-neutral-900/50">
                <p className="text-2xl font-heading text-secondary mb-4 uppercase tracking-wider">No products found</p>
                <p className="text-gray-400 mb-6">Try adjusting your filters or search query.</p>
                <Button variant="outline" onClick={clearFilters}>Clear Filters</Button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Filters Drawer */}
      <AnimatePresence>
        {isMobileFiltersOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsMobileFiltersOpen(false)}
              className="fixed inset-0 bg-black/80 z-[60] md:hidden"
            />
            <motion.div
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'tween', duration: 0.3 }}
              className="fixed top-0 right-0 h-full w-[85vw] max-w-sm bg-neutral-900 z-[70] p-6 overflow-y-auto md:hidden border-l border-white/10"
            >
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-2xl font-heading font-bold text-secondary uppercase tracking-wider">Filters</h2>
                <button onClick={() => setIsMobileFiltersOpen(false)} className="text-gray-400 hover:text-secondary">
                  <FiX className="w-6 h-6" />
                </button>
              </div>
              <FiltersContent />
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}

