        <p className="mt-8 text-center text-sm text-gray-400">
          Already have an account?{' '}
          <Link to="/login" className="text-accent hover:text-white transition-colors font-semibold">
            Sign in
          </Link>
        </p>
      </motion.div>
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { FiFilter, FiX, FiSearch } from 'react-icons/fi';
import ProductCard from '../components/ui/ProductCard';
import QuickViewModal from '../components/ui/QuickViewModal';
import Button from '../components/ui/Button';
import { API_URL } from '../config';

const AVAILABLE_SIZES = ['S', 'M', 'L', 'XL', 'Oversized'];
const AVAILABLE_PRINT_SIZES = ['Left Chest Logo', '15 × 7 cm', 'A4', 'A3', 'Sleeve Print', 'Front + Back'];

export default function Shop() {
  const [searchParams] = useSearchParams();
  const collectionId = searchParams.get('collection');

  const [isMobileFiltersOpen, setIsMobileFiltersOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [priceRange, setPriceRange] = useState([0, 2000]);
  const [selectedSizes, setSelectedSizes] = useState([]);
  const [selectedPrintSizes, setSelectedPrintSizes] = useState([]);

  const [appliedFilters, setAppliedFilters] = useState({
    searchQuery: '',
    priceRange: [0, 2000],
    selectedSizes: [],
    selectedPrintSizes: []
  });

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [collectionName, setCollectionName] = useState('');
  const [collectionType, setCollectionType] = useState('');

  // Quick View State
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [isQuickViewOpen, setIsQuickViewOpen] = useState(false);

  useEffect(() => {
    setLoading(true);
    if (collectionId) {
      fetch(`${API_URL}/collections/${collectionId}`)
        .then(res => res.json())
        .then(data => {
          if (data.success && data.collection && data.collection.products) {
            const mappedProducts = data.collection.products.map(p => ({
              ...p,
              sizes: p.sizes || AVAILABLE_SIZES,
              printSizes: p.printSizes || AVAILABLE_PRINT_SIZES,
            }));
            setProducts(mappedProducts);
            setCollectionName(data.collection.name);
            setCollectionType(data.collection.type);
          } else {
            setProducts([]);
          }
          setLoading(false);
        })
        .catch(err => {
          console.error("Failed to fetch collection:", err);
          setLoading(false);
        });
    } else {
      setCollectionName('');
      setCollectionType('');
      fetch(`${API_URL}/products`)
        .then(res => res.json())
        .then(data => {
          const mappedProducts = data.map(p => ({
            ...p,
            sizes: p.sizes || AVAILABLE_SIZES,
            printSizes: p.printSizes || AVAILABLE_PRINT_SIZES,
          }));
          setProducts(mappedProducts);
          setLoading(false);
        })
        .catch(err => {
          console.error("Failed to fetch products:", err);
          setLoading(false);
        });
    }
  }, [collectionId]);

  const handleOpenQuickView = (product) => {
    setSelectedProduct(product);
    setIsQuickViewOpen(true);
  };


  // Filter Logic
  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      // Search Filter
      const matchesSearch = product.name.toLowerCase().includes(appliedFilters.searchQuery.toLowerCase());

      // Price Filter
      const matchesPrice = product.price >= appliedFilters.priceRange[0] && (appliedFilters.priceRange[1] === 2000 ? true : product.price <= appliedFilters.priceRange[1]);

      // Size Filter
      const matchesSize = appliedFilters.selectedSizes.length === 0 ||
        (product.sizes && appliedFilters.selectedSizes.some(size => product.sizes.includes(size)));

      // Print Size Filter
      const matchesPrintSize = appliedFilters.selectedPrintSizes.length === 0 ||
        (product.printSizes && appliedFilters.selectedPrintSizes.some(ps => product.printSizes.includes(ps)));

      return matchesSearch && matchesPrice && matchesSize && matchesPrintSize;
    });
  }, [products, appliedFilters]);

  const toggleSize = (size) => {
    setSelectedSizes(prev =>
      prev.includes(size) ? prev.filter(s => s !== size) : [...prev, size]
    );
  };

  const togglePrintSize = (size) => {
    setSelectedPrintSizes(prev =>
      prev.includes(size) ? prev.filter(s => s !== size) : [...prev, size]
    );
  };

  const applyFilters = () => {
    setAppliedFilters({
      searchQuery,
      priceRange,
      selectedSizes,
      selectedPrintSizes
    });
  };

  const clearFilters = () => {
    setSearchQuery('');
    setPriceRange([0, 2000]);
    setSelectedSizes([]);
    setSelectedPrintSizes([]);
    setAppliedFilters({
      searchQuery: '',
      priceRange: [0, 2000],
      selectedSizes: [],
      selectedPrintSizes: []
    });
  };

  const FiltersContent = () => (
    <div className="space-y-8">
      {/* Search */}
      <div>
        <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider mb-4">Search</h3>
        <div className="relative">
          <input
            type="text"
            placeholder="Search products..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-neutral-900 border border-white/10 text-secondary px-4 py-3 pl-10 rounded-sm focus:outline-none focus:border-accent transition-colors"
          />
          <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
        </div>
      </div>

      {/* Price Range */}
      <div>
        <div className="flex justify-between mb-4">
          <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider">Price Range</h3>
          <span className="text-accent text-sm">₹{priceRange[0]} - {priceRange[1] === 2000 ? '₹2000+' : `₹${priceRange[1]}`}</span>
        </div>
        <input
          type="range"
          min="0"
          max="2000"
          step="50"
          value={priceRange[1]}
          onChange={(e) => setPriceRange([priceRange[0], parseInt(e.target.value)])}
          className="w-full accent-accent bg-neutral-900 h-1 rounded-full appearance-none outline-none"
        />
      </div>

      {/* Apparel Sizes */}
      <div>
        <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider mb-4">Apparel Size</h3>
        <div className="flex flex-wrap gap-2">
          {AVAILABLE_SIZES.map(size => (
            <button
              key={size}
              onClick={() => toggleSize(size)}
              className={`px-3 py-1.5 text-sm font-body border transition-colors ${selectedSizes.includes(size)
                  ? 'border-accent bg-accent text-primary'
                  : 'border-white/20 text-gray-400 hover:border-white/50'
                }`}
            >
              {size}
            </button>
          ))}
        </div>
      </div>

      {/* Print Sizes */}
      <div>
        <h3 className="text-secondary font-heading font-semibold uppercase tracking-wider mb-4">Print Size</h3>
        <div className="flex flex-wrap gap-2">
          {AVAILABLE_PRINT_SIZES.map(size => (
            <button
              key={size}
              onClick={() => togglePrintSize(size)}
              className={`px-3 py-1.5 text-xs font-body border transition-colors ${selectedPrintSizes.includes(size)
                  ? 'border-accent bg-accent text-primary'
                  : 'border-white/20 text-gray-400 hover:border-white/50'
                }`}
            >
              {size}
            </button>
          ))}
        </div>
      </div>

      <Button variant="primary" size="sm" onClick={applyFilters} className="w-full mb-3">
        Apply Filters
      </Button>
      <Button variant="outline" size="sm" onClick={clearFilters} className="w-full">
        Clear All Filters
      </Button>
    </div>
  );

  return (
    <div className="min-h-screen pt-24 pb-20 bg-primary">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 border-b border-white/10 pb-8">
          <div>
            {collectionName ? (
              <div className="mb-2">
                <span className="inline-block px-3 py-1 bg-accent/20 text-accent border border-accent/50 text-xs font-bold uppercase tracking-wider rounded-full shadow-[0_0_10px_rgba(163,255,18,0.2)] mb-4">
                  {collectionType || 'Collection View'}
                </span>
                <h1 className="text-5xl md:text-7xl font-heading font-bold text-secondary uppercase tracking-tighter">
                  {collectionName}
                </h1>
              </div>
            ) : (
              <h1 className="text-5xl md:text-7xl font-heading font-bold text-secondary uppercase tracking-tighter">
                All <span className="text-accent italic">Products</span>
              </h1>
            )}
            <p className="text-gray-400 mt-2 font-body">Showing {filteredProducts.length} results</p>
          </div>

          <button
            className="md:hidden mt-6 flex items-center gap-2 text-secondary hover:text-accent"
            onClick={() => setIsMobileFiltersOpen(true)}
          >
            <FiFilter /> Filters
          </button>
        </div>

        <div className="flex flex-col md:flex-row gap-12">
          {/* Desktop Sidebar */}
          <aside className="hidden md:block w-64 shrink-0">
            <FiltersContent />
          </aside>

          {/* Product Grid */}
          <div className="flex-1">
            {loading ? (
              <div className="flex flex-col items-center justify-center py-20 text-center text-gray-400">
                Loading products...
              </div>
            ) : filteredProducts.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
                {filteredProducts.map(product => (
                  <ProductCard key={product._id || product.id} product={product} onQuickAdd={handleOpenQuickView} collectionName={collectionName} />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center border border-white/10 rounded-sm bg-neutral-900/50">
                <p className="text-2xl font-heading text-secondary mb-4 uppercase tracking-wider">No products found</p>
                <p className="text-gray-400 mb-6">Try adjusting your filters or search query.</p>
                <Button variant="outline" onClick={clearFilters}>Clear Filters</Button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Filters Drawer */}
      <AnimatePresence>
        {isMobileFiltersOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsMobileFiltersOpen(false)}
              className="fixed inset-0 bg-black/80 z-[60] md:hidden"
            />
            <motion.div
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'tween', duration: 0.3 }}
              className="fixed top-0 right-0 h-full w-[85vw] max-w-sm bg-neutral-900 z-[70] p-6 overflow-y-auto md:hidden border-l border-white/10"
            >
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-2xl font-heading font-bold text-secondary uppercase tracking-wider">Filters</h2>
                <button onClick={() => setIsMobileFiltersOpen(false)} className="text-gray-400 hover:text-secondary">
                  <FiX className="w-6 h-6" />
                </button>
              </div>
              <FiltersContent />
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <QuickViewModal
        product={selectedProduct}
        isOpen={isQuickViewOpen}
        onClose={() => setIsQuickViewOpen(false)}
      />
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';

import { useNavigate } from 'react-router-dom';
import { FiDownload, FiCheckCircle, FiZap, FiBookOpen } from 'react-icons/fi';
import Button from '../components/ui/Button';
import { API_URL } from '../config';
import { useCartStore } from '../store/useCartStore';
import { useUIStore } from '../store/useUIStore';

const PRINT_CATEGORIES = [
  { key: 'Front', label: 'Front Prints', icon: '👕' },
  { key: 'Back', label: 'Back Prints', icon: '🔄' },
  { key: 'Sleeve', label: 'Sleeve Prints', icon: '💪' },
  { key: 'Other', label: 'Other Placements', icon: '✨' },
];



export default function Wholesale() {
  const navigate = useNavigate();
  const addToCart = useCartStore(state => state.addToCart);
  const { alert } = useUIStore();
  const [catalogue, setCatalogue] = useState(null);
  const [quantity, setQuantity] = useState(15);
  const [selectedItem, setSelectedItem] = useState(null);
  const [selectedPrints, setSelectedPrints] = useState([]);
  const [activeCombo, setActiveCombo] = useState(null);
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_URL}/catalogues/live`)
      .then(res => res.json())
      .then(data => {
        setCatalogue(data);
        if (data && data.items && data.items.length > 0) {
          setSelectedItem(data.items[0]);
          setQuantity(data.items[0].moq || 15);
        }
        if (data && data.wholesaleTemplates) {
          const mappedTemplates = data.wholesaleTemplates
            .filter(t => t.isActive && t.templateId)
            .map(t => ({
              ...t.templateId,
              _id: t.templateId._id,
              isRecommended: false
            }));
          setTemplates(mappedTemplates);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Failed to fetch live catalogue:", err);
        setLoading(false);
      });
  }, []);

  const printStyles = useMemo(() => {
    if (!catalogue || !catalogue.wholesaleLocations) return [];
    return catalogue.wholesaleLocations
      .filter(p => p.isActive && p.locationId)
      .map(p => {
        const name = p.locationId.name || 'Unknown';
        // Map to category based on name keywords if possible
        let cat = 'Other';
        if (name.toLowerCase().includes('front') || name.toLowerCase().includes('chest')) cat = 'Front';
        if (name.toLowerCase().includes('back')) cat = 'Back';
        if (name.toLowerCase().includes('sleeve')) cat = 'Sleeve';

        return {
          name: name,
          cost: p.wholesaleCost,
          category: cat,
          size: 'Custom',
          id: p.locationId._id || p._id
        };
      });
  }, [catalogue]);

  // Pricing Logic
  const pricingDetails = useMemo(() => {
    let q = Math.max(0, parseInt(quantity) || 0);
    let minQty = selectedItem ? selectedItem.moq : 15;

    let basePrice = selectedItem ? selectedItem.wholesalePrice : 0;
    let totalPrintCost = selectedPrints.reduce((acc, print) => acc + print.cost, 0);

    let pricePerPiece = basePrice > 0 ? basePrice + totalPrintCost : 0;
    let totalAmount = pricePerPiece * q;

    return {
      isValid: q >= minQty,
      basePrice: basePrice,
      printCost: totalPrintCost,
      printNames: selectedPrints.length > 0 ? selectedPrints.map(p => p.name).join(' + ') : 'Blank',
      pricePerPiece,
      totalAmount,
      q,
      minQty
    };
  }, [quantity, selectedItem, selectedPrints]);

  const togglePrint = (style) => {
    setActiveCombo(null); // Clear active combo when manually toggling
    setSelectedPrints(prev => {
      const isSelected = prev.find(p => p.id === style.id);
      if (isSelected) {
        return prev.filter(p => p.id !== style.id);
      } else {
        return [...prev, style];
      }
    });
  };

  const applyCombo = (combo) => {
    if (activeCombo && activeCombo._id === combo._id) {
      setSelectedPrints([]);
      setActiveCombo(null);
      return;
    }
    const prints = (combo.printAreas || [])
      .map(area => printStyles.find(s => s.name === area.name))
      .filter(Boolean);
    setSelectedPrints(prints);
    setActiveCombo(combo);
  };

  const handlePlaceWholesaleOrder = async () => {
    if (!selectedItem || !pricingDetails.isValid) return;

    addToCart({
      _id: 'wholesale-' + Date.now(),
      id: selectedItem.productId._id || selectedItem.productId,
      productId: selectedItem.productId._id || selectedItem.productId,
      name: selectedItem.productId.name || 'Blank Item',
      price: pricingDetails.pricePerPiece,
      image: selectedItem.productId.image,
      quantity: pricingDetails.q,
      selectedPrints: selectedPrints.map(p => ({ name: p.name, cost: p.cost })),
      orderType: 'Wholesale'
    });

    alert("Added wholesale blanks to cart!", 'success', 'Success');
  };

  if (loading) {
    return <div className="min-h-screen pt-24 flex items-center justify-center text-gray-400">Loading wholesale catalogue...</div>;
  }

  if (!catalogue || !catalogue.items) {
    return <div className="min-h-screen pt-24 flex flex-col gap-4 items-center justify-center text-gray-400">
      <p>No live catalogue available right now.</p>
    </div>;
  }

  return (
    <div className="min-h-screen pt-24 pb-20 bg-primary">
      {/* Hero Section */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-20 text-center">
        <h1 className="text-5xl md:text-7xl font-heading font-bold text-secondary uppercase tracking-tighter mb-6">
          Wholesale <span className="text-accent italic">Partner</span>
        </h1>
        <p className="text-gray-400 max-w-2xl mx-auto font-body text-lg mb-10">
          Start your clothing brand with our premium blanks and DTF printing. MOQ applies based on catalogue.
        </p>
        <div className="flex flex-col sm:flex-row justify-center gap-4">
          <Button variant="accent" size="lg" className="flex items-center gap-2" onClick={() => navigate('/catalogue')}>
            <FiBookOpen /> View Catalogue
          </Button>
          <Button variant="outline" size="lg">
            Contact Sales
          </Button>
        </div>
      </section>

      {/* Pricing Calculator Section */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-neutral-900 border border-white/10 p-8 md:p-12 rounded-lg grid grid-cols-1 lg:grid-cols-2 gap-16">

          {/* Form Side */}
          <div>
            <h2 className="text-3xl font-heading font-bold text-secondary uppercase tracking-wider mb-8 border-b border-white/10 pb-4">
              Instant Quote Calculator
            </h2>

            {/* Category Selector */}
            <div className="mb-8">
              <label className="block text-secondary font-heading font-semibold uppercase tracking-wider mb-4">
                1. Select Product
              </label>
              <div className="space-y-3">
                {catalogue.items.map(item => (
                  <label key={item._id} className="flex items-center p-4 border border-white/10 rounded-sm cursor-pointer hover:border-accent transition-colors">
                    <input
                      type="radio"
                      name="category"
                      className="accent-accent w-4 h-4 mr-4"
                      checked={selectedItem && selectedItem._id === item._id}
                      onChange={() => {
                        setSelectedItem(item);
                        setQuantity(Math.max(quantity, item.moq));
                      }}
                    />
                    <div className="flex flex-col">
                      <span className="text-gray-300 font-body">{item.productId.name || 'Unknown Product'}</span>
                      <span className="text-xs text-gray-500">Wholesale: ₹{item.wholesalePrice} | MOQ: {item.moq}</span>
                    </div>
                  </label>
                ))}
              </div>
            </div>

            {/* Print Style Selector — Grouped by Category */}
            <div className="mb-8">
              <label className="block text-secondary font-heading font-semibold uppercase tracking-wider mb-4">
                2. Select Print Styles (Optional)
              </label>

              {/* Combo Presets */}
              <div className="mb-6">
                <p className="text-gray-500 text-xs font-body uppercase tracking-wider mb-3">Quick Combos</p>
                <div className="flex flex-wrap gap-2">
                  {templates.map(combo => (
                    <button
                      key={combo._id}
                      onClick={() => applyCombo(combo)}
                      className={`flex items-center gap-2 px-3 py-2 border rounded-sm text-sm font-body transition-colors group ${
                          activeCombo && activeCombo._id === combo._id
                            ? 'border-accent bg-accent/10 text-accent'
                            : 'border-white/10 text-gray-300 hover:border-accent hover:text-accent'
                        }`}
                    >
                      <FiZap className="w-3 h-3 text-accent/60 group-hover:text-accent" />
                      <span>{combo.name}</span>
                      {combo.isRecommended && (
                        <span className="text-[10px] px-1.5 py-0.5 bg-accent/15 text-accent rounded-sm">Recommended</span>
                      )}
                      {combo.isPopular && (
                        <span className="text-[10px] px-1.5 py-0.5 bg-accent/15 text-accent rounded-sm">Popular</span>
                      )}
                    </button>
                  ))}
                </div>
              </div>

              {/* Print Styles by Category */}
              <div className="space-y-6">
                {PRINT_CATEGORIES.map(cat => {
                  const styles = printStyles.filter(s => s.category === cat.key);
                  if (styles.length === 0) return null;
                  return (
                    <div key={cat.key}>
                      <p className="text-gray-500 text-xs font-body uppercase tracking-wider mb-3 flex items-center gap-2">
                        <span>{cat.icon}</span> {cat.label}
                      </p>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                        {styles.map(style => {
                          const isSelected = !!selectedPrints.find(p => p.id === style.id);
                          return (
                            <label
                              key={style.name}
                              className={`flex items-center p-3 border rounded-sm cursor-pointer transition-all ${isSelected
                                  ? 'border-accent/50 bg-accent/5'
                                  : 'border-white/10 hover:border-accent/30'
                                }`}
                            >
                              <input
                                type="checkbox"
                                name="printStyle"
                                className="accent-accent w-4 h-4 mr-3 shrink-0"
                                checked={isSelected}
                                onChange={() => togglePrint(style)}
                              />
                              <div className="flex flex-col min-w-0">
                                <span className="text-gray-300 font-body text-sm truncate">{style.name}</span>
                                <div className="flex items-center gap-2">
                                  <span className="text-gray-500 text-xs font-body">{style.size}</span>
                                  <span className="text-accent text-xs font-body">+₹{style.cost}</span>
                                </div>
                              </div>
                            </label>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Quantity Input */}
            <div className="mb-8">
              <label className="block text-secondary font-heading font-semibold uppercase tracking-wider mb-4">
                3. Enter Quantity (Min {pricingDetails.minQty})
              </label>
              <input
                type="number"
                min={pricingDetails.minQty}
                value={quantity}
                onChange={(e) => setQuantity(e.target.value)}
                className="w-full bg-primary border border-white/10 text-secondary px-4 py-4 rounded-sm focus:outline-none focus:border-accent transition-colors font-body text-xl"
              />
              {!pricingDetails.isValid && (
                <p className="text-red-500 text-sm mt-2 font-body">Minimum Order Quantity (MOQ) is {pricingDetails.minQty} pieces.</p>
              )}
            </div>
          </div>

          {/* Pricing Summary Side */}
          <div className="lg:border-l lg:border-white/10 lg:pl-16">
            <div className="sticky top-32">
              <h2 className="text-3xl font-heading font-bold text-secondary uppercase tracking-wider mb-8 border-b border-white/10 pb-4">
                Pricing Summary
              </h2>

              <div className="space-y-6 mb-8 font-body">
                <div className="flex justify-between items-center text-gray-400">
                  <span>Base Price (for {pricingDetails.q} pcs)</span>
                  <span>{pricingDetails.isValid ? `₹${pricingDetails.basePrice}` : '---'}</span>
                </div>
                <div className="flex justify-between items-center text-gray-400">
                  <span className="w-2/3 truncate">Print Cost ({pricingDetails.printNames})</span>
                  <span>+₹{pricingDetails.printCost}</span>
                </div>

                <div className="h-px w-full bg-white/10 my-4"></div>

                <div className="flex justify-between items-center text-xl text-secondary font-bold">
                  <span>Price Per Piece</span>
                  <span>{pricingDetails.isValid ? `₹${pricingDetails.pricePerPiece}` : '---'}</span>
                </div>

                <div className="flex justify-between items-center text-3xl font-heading font-bold text-accent mt-6">
                  <span>Total Est.</span>
                  <span>{pricingDetails.isValid ? `₹${pricingDetails.totalAmount.toLocaleString()}` : '---'}</span>
                </div>
              </div>

              <div className="bg-primary/50 p-6 rounded-sm border border-white/5 mb-8">
                <h4 className="text-secondary font-semibold uppercase tracking-wider mb-4 text-sm">Included in all orders:</h4>
                <ul className="space-y-2 text-gray-400 text-sm">
                  <li className="flex items-center gap-2"><FiCheckCircle className="text-accent" /> Premium Bio-Washed Fabric</li>
                  <li className="flex items-center gap-2"><FiCheckCircle className="text-accent" /> Polybag Packaging</li>
                  <li className="flex items-center gap-2"><FiCheckCircle className="text-accent" /> Size Label (Neck)</li>
                </ul>
              </div>

              {selectedPrints.length > 0 ? (
                <Button
                  variant="accent"
                  size="lg"
                  className="w-full"
                  disabled={!pricingDetails.isValid}
                  onClick={() => navigate('/wholesale/upload', {
                    state: {
                      selectedPrints,
                      pricingDetails,
                      selectedCategory: selectedItem,
                    }
                  })}
                >
                  Proceed to Design Upload
                </Button>
              ) : (
                <Button
                  variant="accent"
                  size="lg"
                  className="w-full bg-blue-600 hover:bg-blue-700 border-blue-600 text-white"
                  disabled={!pricingDetails.isValid}
                  onClick={handlePlaceWholesaleOrder}
                >
                  Add Wholesale Blanks to Cart
                </Button>
              )}
            </div>
          </div>

        </div>
      </section>
    </div>
  );
}
